DDR Inputs
module ddr_in (clk, di, do, clk_out);
   input clk;
   input di;
   output reg [1:0] do;
   output clk_out;

   reg di_neg_ret, di_pos_ret;
   always @ (negedge clk) begin
     di_neg_ret <= di;
   end
   always @ (posedge clk) begin
     di_pos_ret <= di;
     do <= {di_neg_ret, di_pos_ret};
   end
   assign clk_out = clk;

endmodule
DDR Outputs
module ddr_out (clk, di, do, clk_out);
   input clk;
   input [1:0] di;
   output  do;
   output  clk_out;

   reg [1:0] di_ret;
   reg       di_ret1, di_ret0;
   wire      select;

   always @ (posedge clk) begin
     di_ret <= di;
     di_ret1 <= di_ret[1];
   end
   always @ (negedge clk) begin
     di_ret0 <= di_ret[0];
   end 
   assign #0 select = clk;
   assign do = (select) ? di_ret0 : di_ret1;
   assign clk_out = clk;

endmodule
