Examples
set time scale 1.000000 ns ; 
set strobe_window time 10 ;  
 timeplate gen_tp1 = 
    force_pi 0 ;  
    measure_po 10 ;  
    pulse clk 20 10; 
    pulse edt_clock 20 10; 
    pulse ramclk 20 10; 
    period 40 ; 
 end; 
// CREATE A NEW TIMEPLATE THAT MEASURES AFTER THE CLOCK PULSE 
  timeplate gen_tp2 = 
    force_pi 0 ;  
    //    measure_po 10 ;  
    pulse clk 20 10; 
    pulse edt_clock 20 10; 
    pulse ramclk 20 10; 
    measure_po 35 ;       // <<== NEW MEASURE STATEMENT 
    period 40 ; 
 end; 
// FOR CAPTURE SPLIT INTO TWO CYCLES 
 procedure capture = 
    timeplate gen_tp1 ; 
    cycle = 
        force_pi ; 
        measure_po ; 
    end ; 
    cycle = 
        pulse_capture_clock ; 
    end; 
 end; 
// FOR THE SHIFT AND LOAD_UNLOAD, USE THE NEW TIMEPLATE 
 procedure shift = 
    scan_group grp1 ; 
    timeplate gen_tp2 ; //<<=== NEW TIMEPLATE 
    cycle = 
        force_sci ; 
        force edt_update 0 ; 
        measure_sco ; 
        pulse clk ; 
        pulse edt_clock ; 
    end; 
 end; 
// ADD A MEASURE_SCO TO THE LOAD_UNLOAD PROCEDURE 
 procedure load_unload = 
    scan_group grp1 ; 
    timeplate gen_tp2 ; //<<=== NEW TIMEPLATE 
    cycle = 
        force clk 0 ; 
        force edt_bypass 0 ; 
        force edt_clock 0 ; 
        force edt_update 1 ; 
        force ramclk 0 ; 
        force scan_en 1 ; 
        pulse edt_clock ; 
measure_sco;     //<<=== NEW MEASURE STATEMENT 
